files.content:
.root {
  display: grid;
  max-width: 980px;
  margin: 0 auto;
  font-family: Helvetica, Arial, sans-serif;
  font-size: 26px;
}

.root__container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: calc(100vh / 3);
}

.header {
  padding: 10px;
  color: black;
  background: #f2f2f2;
}

.content {
  padding: 10px;
  color: white;
  background: #1f1f1f;
}

.footer {
  padding: 10px;
  background: #2f80ed;
}
